css:
.coherex-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20312a;
    background: linear-gradient(165deg, #f4f1e8 0%, #eef2ea 55%, #e7efe6 100%);
    border-radius: 18px;
}

.coherex-container * {
    box-sizing: border-box;
}

.coherex-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #14342a 0%, #1d5440 55%, #2f7a55 100%);
    color: #f1faf3;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 34px rgba(20, 52, 42, 0.30);
}

.coherex-header h1 {
    margin: 10px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.coherex-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.1px;
    font-weight: 700;
    color: #f3d9a0;
    background: rgba(243, 217, 160, 0.13);
    border: 1px solid rgba(243, 217, 160, 0.36);
    padding: 5px 14px;
    border-radius: 999px;
}

.coherex-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d4ecd9;
}

.coherex-company {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    flex-wrap: wrap;
    background: #ffffff;
    border-left: 5px solid #2f7a55;
    border-radius: 14px;
    padding: 14px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(20, 52, 42, 0.08);
}

.coherex-company-row {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.coherex-company-name {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14342a;
}

.coherex-company-meta {
    font-size: 0.82rem;
    color: #5d6f66;
    line-height: 1.4;
}

.coherex-stamp {
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.4px;
    color: #b23a2e;
    border: 2px solid #d6675a;
    background: rgba(214, 103, 90, 0.08);
    padding: 7px 13px;
    border-radius: 8px;
    transform: rotate(-1.5deg);
    text-transform: uppercase;
}

.coherex-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #44574d;
    margin-bottom: 16px;
    padding: 4px 4px;
}

.coherex-period-counter #currentDay,
.coherex-period-counter #maxPeriods {
    font-weight: 800;
    color: #2f7a55;
}

.coherex-round-name {
    background: rgba(47, 122, 85, 0.14);
    color: #1f6845;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.coherex-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #b23a2e;
    background: rgba(178, 58, 46, 0.12);
    border: 1px solid rgba(178, 58, 46, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.coherex-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 14px;
}

.coherex-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 16px rgba(20, 52, 42, 0.08);
    border-top: 4px solid #2f7a55;
}

.coherex-card-coherence { border-top-color: #2f7a55; }
.coherex-card-invest { border-top-color: #2f6fb0; }
.coherex-card-buyin { border-top-color: #8a5fc0; }
.coherex-card-funding { border-top-color: #d99a1e; }

.coherex-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7c72;
}

.coherex-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #14342a;
    font-variant-numeric: tabular-nums;
}

.coherex-card-coherence .coherex-value { color: #2f7a55; }
.coherex-card-invest .coherex-value { color: #2f6fb0; }
.coherex-card-buyin .coherex-value { color: #8a5fc0; }
.coherex-card-funding .coherex-value { color: #c2860f; }

.coherex-sublabel {
    font-size: 0.76rem;
    color: #76887d;
    line-height: 1.35;
}

.coherex-card-coherence.coherex-coherence-good { border-top-color: #2f7a55; }
.coherex-card-coherence.coherex-coherence-good .coherex-value { color: #2f7a55; }
.coherex-card-coherence.coherex-coherence-bad { border-top-color: #b23a2e; }
.coherex-card-coherence.coherex-coherence-bad .coherex-value { color: #b23a2e; }

.coherex-card-funding.coherex-funding-bad { border-top-color: #b23a2e; }
.coherex-card-funding.coherex-funding-bad .coherex-value { color: #b23a2e; }

.coherex-vitals {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 18px;
}

.coherex-vital {
    flex: 1;
    min-width: 150px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #dde6df;
    border-radius: 11px;
    padding: 10px 16px;
    font-weight: 700;
    font-size: 0.9rem;
    color: #2c3d34;
}

.coherex-vital-label {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: #6a7c72;
    font-weight: 700;
}

.coherex-vital span:last-child {
    font-size: 1.1rem;
    font-weight: 800;
    color: #14342a;
    font-variant-numeric: tabular-nums;
}

.coherex-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #2f7a55;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 52, 42, 0.07);
}

.coherex-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.coherex-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #14342a;
    margin-bottom: 6px;
}

.coherex-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4d43;
}

.coherex-briefing-text strong { color: #1f6845; }
.coherex-briefing-text em { color: #c2860f; font-style: italic; }

.coherex-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 52, 42, 0.07);
}

.coherex-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #14342a;
    border-bottom: 2px solid #e6ece7;
    padding-bottom: 8px;
}

.coherex-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2a3b32;
    margin: 14px 0 6px;
}

.coherex-container select,
.coherex-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c5d2c9;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #ffffff;
    color: #20312a;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.coherex-container select:focus,
.coherex-container input[type="number"]:focus {
    outline: none;
    border-color: #2f7a55;
    box-shadow: 0 0 0 3px rgba(47, 122, 85, 0.16);
}

.coherex-container select option {
    background-color: #ffffff;
    color: #20312a;
}

.coherex-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #2f7a55;
}

.coherex-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #44574d;
    margin-top: 4px;
}

.coherex-range-readout span:nth-child(2) {
    color: #2f7a55;
    font-weight: 800;
}

.coherex-hint {
    font-size: 0.8rem;
    color: #76887d;
    margin-top: 8px;
    line-height: 1.45;
    font-style: italic;
    background: #f3f7f3;
    border-radius: 8px;
    padding: 9px 12px;
}

.coherex-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.coherex-container .btn-primary {
    background: linear-gradient(135deg, #1d5440 0%, #2f7a55 100%);
    border: none;
    color: #ffffff;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(29, 84, 64, 0.32);
}

.coherex-container .btn-primary:hover {
    filter: brightness(1.07);
}

.coherex-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c5d2c9;
    color: #5d6f66;
    background: transparent;
}

.coherex-coach {
    background: linear-gradient(160deg, #14342a 0%, #173d2f 100%);
    color: #e2f1e7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(20, 52, 42, 0.24);
}

.coherex-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f3d9a0;
    margin-bottom: 8px;
}

.coherex-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.coherex-coach-body strong { color: #87e0b3; }
.coherex-coach-body em { color: #f3d9a0; font-style: italic; }

.coherex-history,
.coherex-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(20, 52, 42, 0.07);
}

.coherex-history h3,
.coherex-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #14342a;
}

.coherex-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #3a4d43;
}

.coherex-container table#usfHistoryTable th {
    background: #edf4ee;
    color: #1f6845;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d6e3da;
}

.coherex-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef2ef;
    color: #3a4d43;
}

.coherex-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f6faf7;
}

.coherex-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .coherex-container {
        padding: 14px;
    }
    .coherex-header h1 {
        font-size: 1.7rem;
    }
    .coherex-company {
        flex-direction: column;
        align-items: flex-start;
    }
    .coherex-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .coherex-value {
        font-size: 2rem;
    }
    .coherex-clock {
        margin-left: 0;
    }
    .coherex-period-counter {
        font-size: 0.88rem;
    }
    .coherex-vitals {
        flex-direction: column;
    }
    .coherex-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / committee-debrief screen (coherex) ---- */
.coherex-cm { padding: 8px 4px 4px; color: #e2ede4; }
.coherex-cm-head { text-align: center; margin-bottom: 18px; }
.coherex-cm-score { font-size: 3.4rem; font-weight: 800; line-height: 1; color: #57c08a; }
.coherex-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7fa791; }
.coherex-cm-verdict { font-size: 1.2rem; font-weight: 700; margin-top: 8px; color: #eef7f0; }
.coherex-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.76rem; font-weight: 700; vertical-align: middle; }
.coherex-cm-yes { background: rgba(87,192,138,0.16); color: #57c08a; border: 1px solid rgba(87,192,138,0.5); }
.coherex-cm-no { background: rgba(200,110,80,0.13); color: #d5936f; border: 1px solid rgba(200,110,80,0.45); }
.coherex-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 14px 0; }
.coherex-cm-metric { flex: 1 1 120px; min-width: 100px; background: rgba(87,192,138,0.07); border: 1px solid rgba(87,192,138,0.22); border-radius: 10px; padding: 12px 8px; text-align: center; }
.coherex-cm-mv { display: block; font-size: 1.5rem; font-weight: 800; color: #57c08a; }
.coherex-cm-ml { display: block; font-size: 0.68rem; margin-top: 4px; color: #9fb8a8; text-transform: uppercase; letter-spacing: 0.04em; }
.coherex-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; justify-content: center; margin: 4px 0 16px; }
.coherex-cm-chip { font-size: 0.78rem; font-weight: 600; padding: 4px 12px; border-radius: 999px; border: 1px solid transparent; }
.coherex-cm-chip-on { background: rgba(87,192,138,0.14); color: #86d6a8; border-color: rgba(87,192,138,0.4); }
.coherex-cm-chip-off { background: rgba(159,184,168,0.08); color: #86988c; border-color: rgba(159,184,168,0.22); }
.coherex-cm-debrief-title { font-weight: 700; margin: 10px 0 6px; color: #eef7f0; }
.coherex-cm-insights { margin: 0; padding-left: 20px; }
.coherex-cm-insights li { margin-bottom: 9px; line-height: 1.55; font-size: 0.92rem; color: #cadbce; }

