                        { data: ds.investHistory.map((v) => Math.round(v)) },
                        { data: ds.buyInHistory.map((v) => Math.round(v)) }
                    ]
                }
            };
        }

        _composite(ds) {
            const coherence = Math.round(ds.coherence);
            const invest = Math.round(ds.invest);
            const buyIn = Math.round(ds.buyIn);
            return Math.round(coherence * 0.42 + invest * 0.38 + buyIn * 0.20);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        _gradeLabel(perf) {
            const map = {
                "Plan Passed Over": `grade_passed`,
                "Plan Made Coherent": `grade_coherent`,
                "Conditionally Backable": `grade_conditional`,
                "Core Contradiction Live": `grade_contradiction`,
                "Broken Downstream": `grade_broken`,
                "Low-Leverage Repair": `grade_lowlev`,
                "Coherent but Disowned": `grade_disowned`,
                "Partially Repaired": `grade_partial`
            };
            const key = map[perf];
            return key ? this._cl(key, perf) : perf;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const coherence = Math.round(ds.coherence);
            const invest = Math.round(ds.invest);
            const buyIn = Math.round(ds.buyIn);

            const composite = Math.round(coherence * 0.42 + invest * 0.38 + buyIn * 0.20);

            const coherent = coherence >= 78;
            const investable = invest >= 70;
            const owned = buyIn >= 60;
            const corePositioningFixed = !ds.positioningUnfixed;
            const chainIntact = !ds.pricingBroken;
            const diagnosed = !ds.verdictOnly;
            const leverageRight = !ds.lowLeverage;
            const founderHeld = !ds.ignoredBuyIn;

            // ---- Verdict gates: the headline anti-pattern CANNOT reach the top verdict. ----
            let performance = `Plan Passed Over`;
            if (corePositioningFixed && chainIntact && diagnosed && leverageRight && founderHeld &&
                coherent && investable && owned && composite >= 78) {
                performance = `Plan Made Coherent`;        // funded — the top verdict
            } else if (corePositioningFixed && chainIntact && coherence >= 68 && invest >= 60 && buyIn >= 50) {
                performance = `Conditionally Backable`;     // strong but not airtight
            } else if (ds.positioningUnfixed) {
                performance = `Core Contradiction Live`;    // the headline error path
            } else if (ds.pricingBroken) {
                performance = `Broken Downstream`;          // fixed in isolation
            } else if (ds.lowLeverage) {
                performance = `Low-Leverage Repair`;
            } else if (ds.ignoredBuyIn && coherence >= 60) {
                performance = `Coherent but Disowned`;
            } else if (composite >= 55) {
                performance = `Partially Repaired`;
            }

            const insights = [];
            if (performance === `Plan Made Coherent`) insights.push(window.mySimulation.t(`insight_coherent`));
            else if (ds.positioningUnfixed) insights.push(window.mySimulation.t(`insight_positioning`));
            else if (ds.pricingBroken) insights.push(window.mySimulation.t(`insight_pricing`));
            else if (ds.lowLeverage) insights.push(window.mySimulation.t(`insight_lowleverage`));
            else insights.push(window.mySimulation.t(`insight_mixed`));

            if (ds.verdictOnly) insights.push(window.mySimulation.t(`insight_verdict`));
            if (ds.ignoredBuyIn) insights.push(window.mySimulation.t(`insight_buyin`));
            if (!ds.positioningUnfixed && ds.massCommitted && !ds.pricingBroken) insights.push(window.mySimulation.t(`insight_masspivot`));
            if (!ds.diagnosed && !ds.verdictOnly) insights.push(window.mySimulation.t(`insight_shallow`));
            if (ds.funding > 3.4) insights.push(window.mySimulation.t(`insight_funding`));

            return {
                coherence: coherence,
                invest: invest,
                buyIn: buyIn,
                composite: composite,
                coherent: coherent,
                investable: investable,
                owned: owned,
                corePositioningFixed: corePositioningFixed,
                chainIntact: chainIntact,
                overallScore: composite,
                totalScore: composite,
                met: (corePositioningFixed && chainIntact && diagnosed && leverageRight && founderHeld && coherent && investable && owned && composite >= 78),
                performance: performance,
                performanceLabel: this._gradeLabel(performance),
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const self = this;
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function (k) { return window.mySimulation.t(k); }
                : function (k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const verdict = s.performanceLabel || s.performance || ``;
            const met = !!s.met;
            const badge = met
                ? `<span class="coherex-cm-badge coherex-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="coherex-cm-badge coherex-cm-no">` + T(`cm_notmet`) + `</span>`;
            const chip = function (ok, key) {
                return `<span class="coherex-cm-chip ` + (ok ? `coherex-cm-chip-on` : `coherex-cm-chip-off`) + `">`
                    + (ok ? `✓ ` : `· `) + T(key) + `</span>`;
            };
            const chips = chip(!!s.coherent, `cm_b_coherent`) + chip(!!s.investable, `cm_b_investable`)
                + chip(!!s.owned, `cm_b_owned`) + chip(!!s.chainIntact, `cm_b_chain`);
            const md = function (val, key) {
                return `<div class="coherex-cm-metric"><span class="coherex-cm-mv">` + val
                    + `</span><span class="coherex-cm-ml">` + T(key) + `</span></div>`;
            };
            const metrics = md(Math.round(s.coherence || 0), `cm_m_coherence`)
                + md(Math.round(s.invest || 0), `cm_m_invest`)
                + md(Math.round(s.buyIn || 0), `cm_m_buyin`);
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function (t) { return `<li>` + t + `</li>`; }).join(``);
            return `<div class="coherex-cm">`
                + `<div class="coherex-cm-head">`
                +   `<div class="coherex-cm-score">` + score + `<span class="coherex-cm-score-max">/100</span></div>`
                +   `<div class="coherex-cm-verdict">` + verdict + ` ` + badge + `</div>`
                + `</div>`
                + `<div class="coherex-cm-metrics">` + metrics + `</div>`
                + `<div class="coherex-cm-chips">` + chips + `</div>`
                + `<div class="coherex-cm-debrief-title">` + T(`cm_debrief`) + `</div>`
                + `<ul class="coherex-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.pricingBroken) return window.mySimulation.t(`hint_pricing`);
            if (ds.positioningUnfixed && state.currentPeriod >= 2) return window.mySimulation.t(`hint_positioning`);
            if (ds.verdictOnly) return window.mySimulation.t(`hint_verdict`);
            if (ds.lowLeverage) return window.mySimulation.t(`hint_lowleverage`);
            if (ds.ignoredBuyIn) return window.mySimulation.t(`hint_buyin`);
            if (!ds.positioningUnfixed && ds.coherence >= 70 && ds.invest >= 65) return window.mySimulation.t(`hint_strong`);
            return null;
        }

